# Rust ANI 绑定库：ArkTS 运行时 dlopen 后仅经 ANI_Constructor（#[no_mangle]）注册；
# cxxbridge1$* 与 Rust mangled 符号均由静态内联的 <name>_ani_static 消费（同 DSO 内部），
# 与 build/templates/cxx/ani.versionscript（C++ ANI 库自动注入）的导出面保持一致。
{
  global:
    ANI_Constructor;
  local:
    *;
};
